const snippets={"Python": ["from typing import List, Optional", "from heapq import heapify, heappush, heappop", "", "class Solution:", "", "    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:", "        setattr(ListNode, '__lt__', lambda a, b: a.val < b.val)", "        pq = [head for head in lists if head]", "        heapify(pq)", "        dummy = cur = ListNode()", "        while pq:", "            node = heappop(pq)", "            if node.next:", "                heappush(pq, node.next)", "            cur.next = node", "            cur = cur.next", "        return dummy.next"], "Java": ["import java.util.*;", "class Solution {", "    public ListNode mergeKLists(ListNode[] lists) {", "        PriorityQueue<ListNode> pq = new PriorityQueue<>((a, b) -> a.val - b.val);", "        for (ListNode head : lists) {", "            if (head != null) {", "                pq.offer(head);", "            }", "        }", "        ListNode dummy = new ListNode();", "        ListNode cur = dummy;", "        while (!pq.isEmpty()) {", "            ListNode node = pq.poll();", "            if (node.next != null) {", "                pq.offer(node.next);", "            }", "            cur.next = node;", "            cur = cur.next;", "        }", "        return dummy.next;", "    }", "}"]};
